```cpp
#include <vector>
#include <cstddef>
#include <omp.h>

void gemv(std::vector<double> const& A,
          std::vector<double> const& x,
          std::vector<double> &y,
          size_t M,
          size_t N)
{
    // Expect: A.size() == M*N, x.size() == N, y.size() == M (or will be resized).
    if (y.size() != M) y.assign(M, 0.0);

    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(M); ++i) {
        const size_t row = static_cast<size_t>(i);
        const size_t base = row * N;

        double sum = 0.0; // private to each iteration/thread
        for (size_t j = 0; j < N; ++j) {
            sum += A[base + j] * x[j];
        }
        y[row] = sum; // each row written by exactly one iteration => no races
    }
}
